const express = require('express');
const cors = require('cors');
const pg = require('pg');
require('dotenv').config();
const path = require('path');

console.log('Node.js version:', process.version);
console.log('Starting server setup...');

const app = express();
const port = process.env.PORT || 3000;
console.log(`Server will attempt to listen on port: ${port}`);

app.use(cors());
app.use(express.json());
console.log('CORS and JSON middleware applied.');

console.log('Attempting to create PG Pool...');
const pool = new pg.Pool({
 connectionString: process.env.DATABASE_URL,
 ssl: {
 rejectUnauthorized: false
 }
});
console.log('PG Pool created.');
// Create tables on startup
async function createTables() {
 await pool.query(`
 CREATE TABLE IF NOT EXISTS businesses (
 id SERIAL PRIMARY KEY,
 name TEXT NOT NULL,
 email TEXT UNIQUE NOT NULL,
 password TEXT NOT NULL,
 phone TEXT,
 address TEXT,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
 )
 `);

 await pool.query(`
 CREATE TABLE IF NOT EXISTS services (
 id SERIAL PRIMARY KEY,
 business_id INTEGER REFERENCES businesses(id),
 name TEXT NOT NULL,
 duration INTEGER NOT NULL,
 price INTEGER NOT NULL
 )
 `);

 await pool.query(`
 CREATE TABLE IF NOT EXISTS bookings (
 id SERIAL PRIMARY KEY,
 business_id INTEGER REFERENCES businesses(id),
 service_id INTEGER REFERENCES services(id),
 client_name TEXT NOT NULL,
 client_phone TEXT NOT NULL,
 client_email TEXT,
 booking_date DATE NOT NULL,
 booking_time TIME NOT NULL,
 patient_type TEXT,
 status TEXT DEFAULT 'pending',
 popi_consent BOOLEAN DEFAULT false,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
 )
 `);

 // Add demo business if not exists
 const bizCheck = await pool.query("SELECT id FROM businesses WHERE email = 'demo@eezibook.com'");
 if (bizCheck.rows.length === 0) {
 const bizResult = await pool.query(
 "INSERT INTO businesses (name, email, password, phone) VALUES ($1, $2, $3, $4) RETURNING id",
 ['Demo Business', 'demo@eezibook.com', 'demo123', '+27123456789'
 ]);
 const bizId = bizResult.rows[0].id;

 // Add default services
 await pool.query("INSERT INTO services (business_id, name, duration, price) VALUES ($1, $2, $3, $4)", [bizId, 'General Consultation', 30, 350]);
 await pool.query("INSERT INTO services (business_id, name, duration, price) VALUES ($1, $2, $3, $4)", [bizId, 'Follow-up Visit', 15, 200]);
 await pool.query("INSERT INTO services (business_id, name, duration, price) VALUES ($1, $2, $3, $4)", [bizId, 'Dental Check-up', 45, 400]);
 }

 console.log('Database tables ready.');
}

createTables().then(() => {
 console.log('Defining API routes...');

 // Login Route
 app.post('/api/login', async (req, res) => {
 const { email, password } = req.body;
 try {
 const result = await pool.query(
 'SELECT * FROM businesses WHERE email = $1 AND password = $2',
 [email, password]
 );
 if (result.rows.length > 0) {
 res.json({ id: result.rows[0].id, success: true });
 } else {
 res.status(401).json({ success: false, message: 'Invalid credentials' });
 }
 } catch (err) {
 console.error('Login error:', err.message);
 res.status(500).json({ success: false, message: 'Internal server error' });
 }
 });

 // Get Business Data (includes bookings, services, availability)
 app.get('/api/business/:id', async (req, res) => {
 const business = await pool.query('SELECT * FROM businesses WHERE id = $1', [req.params.id]);
 const services = await pool.query('SELECT * FROM services WHERE business_id = $1', [req.params.id]);
 const availability = await pool.query('SELECT * FROM availability WHERE business_id = $1', [req.params.id]);
 res.json({ ...business.rows[0], services: services.rows, availability: availability.rows });
 });

 // Get Bookings
 app.get('/api/bookings/:businessId', async (req, res) => {
 const bookings = await pool.query(
 `SELECT b.*, s.name as service_name, s.price as service_price
 FROM bookings b LEFT JOIN services s ON b.service_id = s.id
 WHERE b.business_id = $1 ORDER BY booking_date DESC, booking_time DESC`,
 [req.params.businessId]
 );
 res.json(bookings.rows);
 });

 // Get Services
 app.get('/api/services/:businessId', async (req, res) => {
 const services = await pool.query('SELECT * FROM services WHERE business_id = $1', [req.params.businessId]);
 res.json(services.rows);
 });
 // Add Service
 app.post('/api/services', async (req, res) => {
 const { business_id, name, duration, price } = req.body;
 const result = await pool.query(
 "INSERT INTO services (business_id, name, duration, price) VALUES ($1, $2, $3, $4) RETURNING *",
 [business_id, name, duration, price]
 );
 res.json(result.rows[0]);
 });

 // Delete Service
 app.delete('/api/services/:id', async (req, res) => {
 await pool.query('DELETE FROM services WHERE id = $1', [req.params.id]);
 res.json({ success: true });
 });

 // Create Booking
 app.post('/api/bookings', async (req, res) => {
 const { business_id, service_id, client_name, client_phone, client_email, booking_date, booking_time, patient_type, popi_consent } = req.body;
 const result = await pool.query(
 `INSERT INTO bookings (business_id, service_id, client_name, client_phone, client_email, booking_date, booking_time, patient_type, popi_consent)
 VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9) RETURNING *`,
 [business_id, service_id, client_name, client_phone, client_email, booking_date, booking_time, patient_type, popi_consent]
 );
 res.json(result.rows[0]);
 });

 console.log('API routes defined.');
 // Static File Serving
 app.use(express.static(path.join(__dirname, 'public')));
 console.log(`Static files from '${path.join(__dirname, 'public')}' will be served.`);

 // Start Server
 app.listen(port, () => {
 console.log(`EeziBook server running on port ${port}`);
 });
});
