const express = require('express');
const cors = require('cors');
const { Pool } = require('pg');

const app = express();
const PORT = process.env.PORT || 3000;

// PostgreSQL connection
const pool = new Pool({
  connectionString: process.env.DATABASE_URL || 'postgres://eezibook_user:YOUR_PASSWORD@localhost:5432/eezibook'
});

// Middleware
app.use(cors());
app.use(express.json());
app.use(express.static('public'));

// Initialize database tables
async function initDB() {
  await pool.query(`
    CREATE TABLE IF NOT EXISTS businesses (
      id SERIAL PRIMARY KEY,
      name TEXT NOT NULL,
      phone TEXT,
      email TEXT UNIQUE NOT NULL,
      password TEXT NOT NULL,
      created_at TIMESTAMP DEFAULT NOW()
    )
  `);

  await pool.query(`
    CREATE TABLE IF NOT EXISTS services (
      id SERIAL PRIMARY KEY,
      business_id INTEGER REFERENCES businesses(id),
      name TEXT NOT NULL,
      duration INTEGER NOT NULL,
      price INTEGER NOT NULL
    )
  `);

  await pool.query(`
    CREATE TABLE IF NOT EXISTS availability (
      id SERIAL PRIMARY KEY,
      business_id INTEGER REFERENCES businesses(id),
      day_of_week INTEGER NOT NULL,
      start_time TEXT NOT NULL,
      end_time TEXT NOT NULL
    )
  `);

  await pool.query(`
    CREATE TABLE IF NOT EXISTS bookings (
      id SERIAL PRIMARY KEY,
      business_id INTEGER REFERENCES businesses(id),
      service_id INTEGER REFERENCES services(id),
      client_name TEXT NOT NULL,
      client_email TEXT,
      client_phone TEXT,
      booking_date TEXT NOT NULL,
      booking_time TEXT NOT NULL,
      status TEXT DEFAULT 'confirmed',
      created_at TIMESTAMP DEFAULT NOW()
    )
  `);

  // Check if demo exists
  const demo = await pool.query("SELECT id FROM businesses WHERE email = 'demo@eezibook.com'");
  if (demo.rows.length === 0) {
    // Create demo business
    const biz = await pool.query(
      "INSERT INTO businesses (name, phone, email, password) VALUES ($1, $2, $3, $4) RETURNING id",
      ['Demo Medical Practice', '+27821234567', 'demo@eezibook.com', 'demo123']
    );
    const bizId = biz.rows[0].id;

    // Add services
    await pool.query("INSERT INTO services (business_id, name, duration, price) VALUES ($1, $2, $3, $4)", [bizId, 'General Consultation', 30, 350]);
    await pool.query("INSERT INTO services (business_id, name, duration, price) VALUES ($1, $2, $3, $4)", [bizId, 'Follow-up Visit', 15, 200]);
    await pool.query("INSERT INTO services (business_id, name, duration, price) VALUES ($1, $2, $3, $4)", [bizId, 'Dental Check-up', 45, 400]);

    // Add availability (Mon-Fri, 9am-6pm)
    for (let day = 1; day <= 5; day++) {
      await pool.query("INSERT INTO availability (business_id, day_of_week, start_time, end_time) VALUES ($1, $2, $3, $4)", [bizId, day, '09:00', '18:00']);
    }
    console.log('Demo business created: demo@eezibook.com / demo123');
  }
}

initDB().catch(console.error);

// API Routes

app.get('/api/business/:id', async (req, res) => {
  const business = await pool.query("SELECT * FROM businesses WHERE id = $1", [req.params.id]);
  if (business.rows.length === 0) return res.status(404).json({ error: 'Business not found' });

  const services = await pool.query("SELECT * FROM services WHERE business_id = $1", [req.params.id]);
  const availability = await pool.query("SELECT * FROM availability WHERE business_id = $1", [req.params.id]);

  res.json({ ...business.rows[0], services: services.rows, availability: availability.rows });
});

app.get('/api/businesses', async (req, res) => {
