app.get('/api/slots/:businessId/:date', async (req, res) => {
  const { businessId, date } = req.params;
  const dayOfWeek = new Date(date).getDay();

  const avail = await pool.query("SELECT * FROM availability WHERE business_id = $1 AND day_of_week = $2", [businessId, dayOfWeek]);
  if (avail.rows.length === 0) return res.json([]);

  const dayBookings = await pool.query("SELECT booking_time FROM bookings WHERE business_id = $1 AND booking_date = $2", [businessId, date]);
