```javascript
// Get available time slots for a specific date
app.get('/api/slots/:businessId/:date', async (req, res) => {
  const { businessId, date } = req.params;
  const dayOfWeek = new Date(date).getDay();

  // Closed on Sundays (0) and Saturdays (6)
  if (dayOfWeek === 0 || dayOfWeek === 6) return res.json([]);

  // Fixed hours: 9am to 6pm, 30-min slots
  const slots = [];
  for (let hour = 9; hour < 18; hour++) {
    for (let min = 0; min < 60; min += 30) {
      slots.push(`${String(hour).padStart(2, '0')}:${String(min).padStart(2, '0')}`);
    }
  }

  // Get booked times from database
  try {
    const bookings = await pool.query(
      'SELECT booking_time FROM bookings WHERE business_id = $1 AND booking_date = $2',
      [businessId, date]
    );
    const bookedTimes = bookings.rows.map(b => b.booking_time);
    const availableSlots = slots.filter(slot => !bookedTimes.includes(slot));
    res.json(availableSlots);
  } catch (err) {
    // If DB fails, just return all slots
    res.json(slots);
  }
});
