 const nextWeekEnd = new Date(nextWeekStart);
 nextWeekEnd.setDate(nextWeekStart.getDate() + 6);

 const todayCount = bookings.filter(b => b.booking_date === todayStr).length;
 const thisWeekCount = bookings.filter(b => new Date(b.booking_date) >= thisWeekStart && new Date(b.booking_date) <= thisWeekEnd).length;
 const nextWeekCount = bookings.filter(b => new Date(b.booking_date) >= nextWeekStart && new Date(b.booking_date) <= nextWeekEnd).length;

 document.getElementById('todayCount').textContent = todayCount;
 document.getElementById('weekCount').textContent = thisWeekCount;
 document.getElementById('nextWeekCount').textContent = nextWeekCount;

 const tomorrow = new Date(today);
 tomorrow.setDate(tomorrow.getDate() + 1);
 const tomorrowStr = tomorrow.toISOString().split('T')[0];

 const bookingsToday = bookings.filter(b => b.booking_date === todayStr);
 const bookingsTomorrow = bookings.filter(b => b.booking_date === tomorrowStr);
 const bookingsThisWeek = bookings.filter(b => { const d = new Date(b.booking_date); return d >= thisWeekStart && d <= thisWeekEnd; });
 const bookingsNextWeek = bookings.filter(b => { const d = new Date(b.booking_date); return d >= nextWeekStart && d <= nextWeekEnd; });
 const bookingsNextMonth = bookings.filter(b => { const d = new Date(b.booking_date); return d.getMonth() === today.getMonth() + 1; });

 // Sort by time within each group
 const sortByTime = (a, b) => new Date('1970-01-01 ' + a.booking_time) - new Date('1970-01-01 ' + b.booking_time);

 const container = document.getElementById('bookingsList');
 container.innerHTML = '';

 const sections = [
 { title: "Today's Bookings", list: bookingsToday.sort(sortByTime) },
 { title: "Tomorrow's Bookings", list: bookingsTomorrow.sort(sortByTime) },
 { title: "This Week's Bookings", list: bookingsThisWeek.sort(sortByTime) },
 { title: "Next Week's Bookings", list: bookingsNextWeek.sort(sortByTime) },
 { title: "Next Month's Bookings", list: bookingsNextMonth.sort(sortByTime) }
 ];

 sections.forEach((section) => {
 const count = section.list.length;
 const sectionDiv = document.createElement('div');
 sectionDiv.innerHTML = `
 <div class="section-header" onclick="toggleBookingSection(this)" style="cursor:pointer;display:flex;justify-content:space-between;align-items:center;padding:12px;background:#f5f5f5;border-radius:8px;margin-bottom:10px;">
 <span>${section.title} (${count})</span>
 <span class="toggle-icon">▼</span>
 </div>
 <div class="section-content" style="padding-bottom:15px;">
 ${count === 0 ? '<p style="color:#666;text-align:center;">No bookings</p>' : ''}
 </div>
 `;
 container.appendChild(sectionDiv);

 const contentDiv = sectionDiv.querySelector('.section-content');
 section.list.forEach(b => {
 const div = document.createElement('div');
 div.style.marginBottom = '8px';
 div.style.display = 'flex';
 div.style.justifyContent = 'space-between';
 div.style.alignItems = 'center';
 div.innerHTML = `
 <div>
 <strong>${b.client_name}</strong><br>
 <span style="font-size:0.85rem;color:#666;">${b.client_phone} | ${b.client_email || 'No email'}</span><br>
 <span style="font-size:0.85rem;color:#888;">${b.patient_type || 'Private Patient'}</span>
 </div>
 <div style="text-align:right;">
 <div>${b.booking_date}</div>
 <div style="color:#256DEB;font-weight:600;">${b.booking_time}</div>
 </div>
 `;
 contentDiv.appendChild(div);
 });
 });
 }

 function toggleBookingSection(header) {
 const content = header.nextElementSibling;
