 const today = new Date();
 const todayStr = today.toISOString().split('T')[0];

 const tomorrow = new Date(today);
 tomorrow.setDate(tomorrow.getDate() + 1);
 const tomorrowStr = tomorrow.toISOString().split('T')[0];

 const thisWeekStart = new Date(today);
 thisWeekStart.setDate(today.getDate() - (today.getDay() - 1));
 const thisWeekEnd = new Date(thisWeekStart);
 thisWeekEnd.setDate(thisWeekStart.getDate() + 6);

 const nextWeekStart = new Date(thisWeekStart);
 nextWeekStart.setDate(thisWeekStart.getDate() + 7);
 const nextWeekEnd = new Date(nextWeekStart);
 nextWeekEnd.setDate(nextWeekStart.getDate() + 6);

 const todayCount = bookings.filter(b => b.booking_date === todayStr).length;
 const thisWeekCount = bookings.filter(b => new Date(b.booking_date) >= thisWeekStart && new Date(b.booking_date) <= thisWeekEnd).length;
 const nextWeekCount = bookings.filter(b => new Date(b.booking_date) >= nextWeekStart && new Date(b.booking_date) <= nextWeekEnd).length;

 document.getElementById('todayCount').textContent = todayCount;
 document.getElementById('weekCount').textContent = thisWeekCount;
 document.getElementById('nextWeekCount').textContent = nextWeekCount;

 const bookingsToday = bookings.filter(b => b.booking_date === todayStr);
 const bookingsTomorrow = bookings.filter(b => b.booking_date === tomorrowStr);
 const bookingsThisWeek = bookings.filter(b => { const d = new Date(b.booking_date); return d >= thisWeekStart && d <= thisWeekEnd; });
 const bookingsNextWeek = bookings.filter(b => { const d = new Date(b.booking_date); return d >= nextWeekStart && d <= nextWeekEnd; });
 const bookingsNextMonth = bookings.filter(b => { const d = new Date(b.booking_date); return d.getMonth() === today.getMonth() + 1; });

 // Sort by date AND time (earliest first)
 function sortByDateAndTime(a, b) {
  const dateA = new Date(a.booking_date + ' ' + a.booking_time);
  const dateB = new Date(b.booking_date + ' ' + b.booking_time);
  return dateA - dateB;
 }

